                abstract_top=l['bbox'][1]
    cand=[(t,b,s) for t,b,s in lines if (abstract_top is None or b[1] < abstract_top)
          and not re.search(r'arxiv|preprint', t, re.I)
          and '@' not in t]
    if not cand:
        return None, abstract_top
    max_size=max(s for _,_,s in cand)
    title_lines=[(t,b,s) for t,b,s in cand if s>=max_size*0.9]
    title_bottom=max(b[3] for _,b,_ in title_lines)
    return title_bottom, abstract_top

for src in srcs:
    doc=fitz.open(src)
    # Strip metadata fields
    meta = {k: '' for k in doc.metadata}
    doc.set_metadata(meta)
    try:
