    except Exception:
        pass

    if doc.page_count>0:
        page0=doc[0]
        title_bottom, abstract_top = get_title_and_abstract(page0)
    else:
        title_bottom=abstract_top=None

    author_tokens=set()
    if doc.page_count>0 and title_bottom and abstract_top and title_bottom < abstract_top:
        d=page0.get_text('dict')
        for b in d['blocks']:
            for l in b.get('lines', []):
                text=''.join(s['text'] for s in l.get('spans', [])).strip()
                if not text:
                    continue
                y0,y1=l['bbox'][1], l['bbox'][3]
                if y0 >= title_bottom-1 and y1 <= abstract_top+1:
                    for tok in re.findall(r'[A-Z][A-Za-z\-]+', text):
                        if len(tok) >= 3:
                            author_tokens.add(tok.lower())

    for pno, page in enumerate(doc):
        d=page.get_text('dict')
        for b in d['blocks']:
            for l in b.get('lines', []):
                text=''.join(s['text'] for s in l.get('spans', [])).strip()
                if not text:
                    continue
                redact=False

                if email_re.search(text):
                    redact=True

                if repo_re.search(text):
                    if pno <= 2:
                        redact=True
                    else:
                        for tok in author_tokens:
                            if tok in text.lower():
                                redact=True
                                break

                if pno == 0:
                    if any(p.search(text) for p in page0_patterns):
                        redact=True
                    if affil_keywords.search(text):
                        redact=True
                    if text.count(',') >= 2:
                        redact=True

                if redact:
                    page.add_redact_annot(fitz.Rect(l['bbox']), fill=(1,1,1))

        if pno == 0 and title_bottom and abstract_top and title_bottom < abstract_top:
            rect = fitz.Rect(0, title_bottom-2, page.rect.width, abstract_top+2)
            page.add_redact_annot(rect, fill=(1,1,1))

        page.apply_redactions()

    dst = dst_dir / Path(src).name
    doc.save(dst)
    doc.close()
    print('saved', dst)
